-- All fixture registrations and admin updates are rolled back. No notification is produced.
begin;
do $$
declare
  p jsonb:=jsonb_build_object('full_name','בדיקת מסד בלבד','registrant_kind','guardian','contact_name','הורה בדיקת מסד','contact_phone','0500000000','contact_email','test@example.invalid','group_name','beginners','branch','herzog','current_rank','white','payment_method','bit','accuracy_consent',true,'guardian_consent',true,'consent_version','2026-10-11.1');
  k text:=repeat('a',64); ph text:=repeat('b',64); ih text:=repeat('c',64); sh text:=repeat('d',64);
  r jsonb; ref text; reg public.grade_exam_registrations%rowtype; actor uuid; count_before bigint;
begin
  select count(*) into count_before from public.grade_exam_registrations;
  if has_table_privilege('anon','public.grade_exam_registrations','SELECT') or has_table_privilege('authenticated','public.grade_exam_registrations','SELECT') then raise exception 'Public table visibility'; end if;
  if has_function_privilege('anon','public.register_grade_exam_contact(jsonb,text,text,text,text)','EXECUTE') or has_function_privilege('authenticated','public.report_grade_exam_payment(text,text,text)','EXECUTE') then raise exception 'Public RPC visibility'; end if;
  r:=public.register_grade_exam_contact(p,k,ph,ih,sh);
  if r->>'ok'<>'true' or r#>>'{registration,amount_agorot}'<>'10000' or r#>>'{registration,payment_status}'<>'awaiting_payment' or r#>>'{registration,registration_status}'<>'pending' then raise exception 'Registration failed: %',r; end if;
  ref:=r#>>'{registration,reference}';
  select * into reg from public.grade_exam_registrations where reference=ref;
  if reg.national_id is not null or reg.birth_date is not null then raise exception 'Removed identity fields were stored'; end if;
  if r->'registration' ?| array['national_id','birth_date','full_name','request_key_hash','contact_phone'] then raise exception 'Receipt contains personal data'; end if;
  r:=public.register_grade_exam_contact(p,k,ph,ih,sh);
  if r->>'replayed'<>'true' or r#>>'{registration,reference}'<>ref then raise exception 'Retry duplicated registration'; end if;
  r:=public.register_grade_exam_contact(p||'{"full_name":"שם ששונה"}'::jsonb,k,repeat('e',64),ih,sh);
  if r->>'code'<>'KEY_CONFLICT' then raise exception 'Changed payload not rejected'; end if;
  r:=public.register_grade_exam_contact(p,repeat('1',64),ph,repeat('0',64),sh);
  if r->>'code'<>'DUPLICATE_REGISTRATION' then raise exception 'Identity duplicate not rejected'; end if;
  r:=public.register_grade_exam_contact(p||'{"guardian_consent":false}'::jsonb,repeat('2',64),ph,repeat('3',64),sh);
  if r->>'code'<>'INVALID' then raise exception 'Guardian without consent accepted'; end if;
  r:=public.register_grade_exam_contact(p||'{"contact_name":""}'::jsonb,repeat('2',64),ph,repeat('3',64),sh);
  if r->>'code'<>'INVALID' then raise exception 'Missing contact name accepted'; end if;
  r:=public.register_grade_exam_contact(p||'{"current_rank":"black"}'::jsonb,repeat('2',64),ph,repeat('3',64),sh);
  if r->>'code'<>'INVALID' then raise exception 'Unsupported rank accepted'; end if;
  r:=public.register_grade_exam_contact(p||'{"contact_phone":"123"}'::jsonb,repeat('2',64),ph,repeat('3',64),sh);
  if r->>'code'<>'INVALID' then raise exception 'Invalid phone accepted'; end if;
  r:=public.register_grade_exam_contact(p||'{"contact_email":"invalid"}'::jsonb,repeat('2',64),ph,repeat('3',64),sh);
  if r->>'code'<>'INVALID' then raise exception 'Invalid email accepted'; end if;
  r:=public.report_grade_exam_payment(ref,repeat('f',64),'אסמכתה בדיקה');
  if r->>'code'<>'NOT_FOUND' then raise exception 'Wrong capability accepted'; end if;
  r:=public.report_grade_exam_payment(ref,k,'אסמכתה בדיקה');
  if r#>>'{registration,payment_status}'<>'reported_unverified' then raise exception 'Self report verified a payment'; end if;
  r:=public.report_grade_exam_payment(ref,k,'אסמכתה בדיקה');
  if r->>'replayed'<>'true' then raise exception 'Report retry was not idempotent'; end if;
  select * into reg from public.grade_exam_registrations where reference=ref;
  select id into actor from public.profiles where role='admin' and approval_status='approved' limit 1;
  if actor is null then raise exception 'No approved administrator for rolled-back tests'; end if;
  r:=public.admin_update_grade_exam(reg.id,actor,reg.updated_at,'verified','pending',false,'בדיקת מסד בלבד');
  if r->>'code'<>'PAYMENT_EVIDENCE_REQUIRED' then raise exception 'Unconfirmed verification accepted'; end if;
  r:=public.admin_update_grade_exam(reg.id,actor,reg.updated_at,'reported_unverified','approved',false,'בדיקת מסד בלבד');
  if r->>'code'<>'PAYMENT_REQUIRED' then raise exception 'Unpaid attendance approved'; end if;
  r:=public.admin_update_grade_exam(reg.id,actor,reg.updated_at-interval '1 second','verified','approved',true,'בדיקת מסד בלבד');
  if r->>'code'<>'STALE_RECORD' then raise exception 'Stale write accepted'; end if;
  r:=public.admin_update_grade_exam(reg.id,actor,reg.updated_at,'verified','approved',true,'בדיקת מסד בלבד');
  if r->>'ok'<>'true' then raise exception 'Confirmed admin verification failed'; end if;
  r:=public.report_grade_exam_payment(ref,k,'דיווח חוזר לבדיקה');
  if r#>>'{registration,payment_status}'<>'verified' then raise exception 'Self report downgraded verified payment'; end if;
  select * into reg from public.grade_exam_registrations where reference=ref;
  r:=public.admin_update_grade_exam(reg.id,actor,reg.updated_at,'verified','cancelled',false,'ביטול לצורך בדיקת מסד');
  if r->>'ok'<>'true' then raise exception 'Cancellation failed'; end if;
  r:=public.report_grade_exam_payment(ref,k,'דיווח לאחר ביטול');
  if r->>'code'<>'CANCELLED' then raise exception 'Cancelled registration report accepted'; end if;
  r:=public.register_grade_exam_contact(p||'{"payment_method":"cash","amount_agorot":1,"payment_status":"verified"}'::jsonb,repeat('4',64),repeat('5',64),ih,sh);
  if r->>'ok'<>'true' or r#>>'{registration,amount_agorot}'<>'10000' or r#>>'{registration,payment_status}'<>'awaiting_payment' then raise exception 'Cash re-registration or trusted price failed'; end if;
  r:=public.report_grade_exam_payment(r#>>'{registration,reference}',repeat('4',64),'דיווח מזומן');
  if r->>'code'<>'CASH_PAYMENT' then raise exception 'Public cash reporting accepted'; end if;
  insert into public.grade_exam_intake_limits(source_hash,hour_start,attempts) values(repeat('6',64),date_trunc('hour',now()),20);
  r:=public.register_grade_exam_contact(p||'{"current_rank":"yellow","payment_method":"paybox"}'::jsonb,repeat('7',64),ph,ih,repeat('6',64));
  if r->>'code'<>'RATE_LIMITED' then raise exception 'Rate limit ignored'; end if;
  r:=public.register_grade_exam_contact(p||'{"current_rank":"yellow","payment_method":"paybox"}'::jsonb,repeat('7',64),ph,ih,sh);
  if r->>'ok'<>'true' or r#>>'{registration,payment_method}'<>'paybox' then raise exception 'New rank / PayBox registration failed'; end if;
  r:=public.register_grade_exam_contact(p||'{"current_rank":"yellow","payment_method":"paybox"}'::jsonb,repeat('7',64),ph,ih,repeat('6',64));
  if r->>'replayed'<>'true' then raise exception 'Rate limit blocked a successful retry'; end if;
  r:=public.register_grade_exam_contact(p||'{"full_name":"חניך אחר עם אותו טלפון"}'::jsonb,repeat('8',64),ph,repeat('9',64),sh);
  if r->>'ok'<>'true' then raise exception 'Sibling sharing a contact phone was blocked'; end if;
  if (select count(*) from public.grade_exam_registrations)<>count_before+4 then raise exception 'Unexpected registration count'; end if;
end;
$$;
rollback;
select true as grade_exam_contact_only_database_checks_passed, count(*) as retained_registrations from public.grade_exam_registrations;
